Add-Type @'
using System.Runtime.InteropServices;

public static class DbgTest
{
    [DllImport(
        "kernel32.dll",
        EntryPoint = "OutputDebugStringA",
        ExactSpelling = true,
        CharSet = CharSet.Ansi)]
    public static extern void Write(
        [MarshalAs(UnmanagedType.LPStr)] string text);
}
'@


1..20 | ForEach-Object {
    [DbgTest]::Write("DBWIN test message $_ ")
}